CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(40) UNIQUE, pw_hash VARCHAR(255), created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rice_types (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80), country VARCHAR(80), grain VARCHAR(10), info TEXT);
CREATE TABLE IF NOT EXISTS samples (id INT AUTO_INCREMENT PRIMARY KEY, label VARCHAR(80), score FLOAT, grade VARCHAR(8), broken FLOAT, grain VARCHAR(10), verdict VARCHAR(10), variety VARCHAR(80), country VARCHAR(80), user_id INT, created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alerts (id INT AUTO_INCREMENT PRIMARY KEY, severity VARCHAR(10), message VARCHAR(255), created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
